1547	    @Nonnull
1548	    protected <M extends Message> CompletableFuture<Boolean> deleteTypedRecord(@Nonnull RecordSerializer<M> typedSerializer,
1549	                                                                               @Nonnull Tuple primaryKey, boolean isDryRun) {
1550	        if (isDryRun) {
1551	            return loadTypedRecord(typedSerializer, primaryKey, false).thenCompose(oldRecord -> oldRecord == null ? AsyncUtil.READY_FALSE : AsyncUtil.READY_TRUE);
1552	        }
1553	        preloadCache.invalidate(primaryKey);
1554	        final RecordMetaData metaData = metaDataProvider.getRecordMetaData();
1555	        CompletableFuture<Boolean> result = loadTypedRecord(typedSerializer, primaryKey, false).thenCompose(oldRecord -> {
1556	            if (oldRecord == null) {
1557	                return AsyncUtil.READY_FALSE;
1558	            }
1559	            SplitHelper.deleteSplit(getRecordContext(), recordsSubspace(), primaryKey, metaData.isSplitLongRecords(), omitUnsplitRecordSuffix, true, oldRecord);
1560	            countKeysAndValues(FDBStoreTimer.Counts.DELETE_RECORD_KEY, FDBStoreTimer.Counts.DELETE_RECORD_KEY_BYTES, FDBStoreTimer.Counts.DELETE_RECORD_VALUE_BYTES,
1561	                    oldRecord);
1562	            addRecordCount(metaData, oldRecord, LITTLE_ENDIAN_INT64_MINUS_ONE);
1563	            final boolean oldHasIncompleteVersion = oldRecord.hasVersion() && !oldRecord.getVersion().isComplete();
1564	            if (useOldVersionFormat()) {
1565	                byte[] versionKey = getSubspace().pack(recordVersionKey(primaryKey));
1566	                if (oldHasIncompleteVersion) {
1567	                    context.removeVersionMutation(versionKey);
1568	                } else if (metaData.isStoreRecordVersions()) {
1569	                    ensureContextActive().clear(versionKey);
1570	                }
1571	            }
1572	            CompletableFuture<Void> updateIndexesFuture = updateSecondaryIndexes(oldRecord, null);
1573	            if (oldHasIncompleteVersion) {
1574	                return updateIndexesFuture.thenApply(vignore -> {
1575	                    byte[] versionKey = getSubspace().pack(recordVersionKey(primaryKey));
1576	                    context.removeLocalVersion(versionKey);
1577	                    return true;
1578	                });
1579	            } else {
1580	                return updateIndexesFuture.thenApply(vignore -> true);
1581	            }
1582	        });
1583	        return context.instrument(FDBStoreTimer.Events.DELETE_RECORD, result);
1584	    }
