1600	    /**
1601	     * Delete the record store at the given {@link Subspace}. In addition to the store's
1602	     * data this will delete the store's header and therefore will remove any evidence that
1603	     * the store existed.
1604	     *
1605	     * <p>
1606	     * This method does not read the underlying record store, so it does not validate
1607	     * that a record store exists in the given subspace. As it might be the case that
1608	     * this record store has a cacheable store state (see {@link #setStateCacheability(boolean)}),
1609	     * this method resets the database's
1610	     * {@linkplain FDBRecordContext#getMetaDataVersionStamp(IsolationLevel) meta-data version-stamp}.
1611	     * As a result, calling this method may cause other clients to invalidate their caches needlessly.
1612	     * </p>
1613	     *
1614	     * @param context the transactional context in which to delete the record store
1615	     * @param subspace the subspace containing the record store
1616	     */
1617	    @SuppressWarnings("PMD.CloseResource")
1618	    public static void deleteStore(FDBRecordContext context, Subspace subspace) {
1619	        // In theory, we only need to set the meta-data version stamp if the record store's
1620	        // meta-data is cacheable, but we can't know that from here.
1621	        context.setMetaDataVersionStamp();
1622	        context.setDirtyStoreState(true);
1623	        final Transaction transaction = context.ensureActive();
1624	        transaction.clear(subspace.range());
1625	    }
